import requests

ACCESS_TOKEN = "YOUR_ACCESS_TOKEN"
BASE_URL = "https://api.spotify.com/v1"
headers = {"Authorization": f"Bearer {ACCESS_TOKEN}"}

playlists_response = requests.get(
    f"{BASE_URL}/me/playlists",
    headers=headers,
    params={"limit": 50},
)
playlists_response.raise_for_status()

playlist = next(
    (item for item in playlists_response.json().get("items", []) if item.get("name") == "My R&B"),
    None,
)
if playlist is None:
    raise ValueError("Playlist 'My R&B' was not found.")

playlist_id = playlist["id"]
artist_ids = set()
offset = 0

while True:
    tracks_response = requests.get(
        f"{BASE_URL}/playlists/{playlist_id}/tracks",
        headers=headers,
        params={"limit": 100, "offset": offset},
    )
    tracks_response.raise_for_status()
    data = tracks_response.json()

    for item in data.get("items", []):
        track = item.get("track") or {}
        for artist in track.get("artists", []):
            if artist.get("id"):
                artist_ids.add(artist["id"])

    offset += len(data.get("items", []))
    if not data.get("next") or not data.get("items"):
        break

for start in range(0, len(artist_ids), 50):
    batch = list(artist_ids)[start:start + 50]
    response = requests.put(
        f"{BASE_URL}/me/following",
        headers=headers,
        params={"type": "artist", "ids": ",".join(batch)},
    )
    response.raise_for_status()

