import os
import requests

BASE_URL = "https://api.spotify.com/v1"
headers = {"Authorization": f"Bearer {os.environ['SPOTIFY_ACCESS_TOKEN']}"}

response = requests.get(
    f"{BASE_URL}/search",
    headers=headers,
    params={"q": "My R&B", "type": "playlist"},
)
response.raise_for_status()

playlists = response.json().get("playlists", {}).get("items", [])
playlist = next((item for item in playlists if item.get("name") == "My R&B"), None)
if playlist is None:
    raise ValueError("Playlist 'My R&B' was not found")

response = requests.get(
    f"{BASE_URL}/playlists/{playlist['id']}/tracks",
    headers=headers,
    params={"limit": 100},
)
response.raise_for_status()

artist_ids = {
    artist["id"]
    for item in response.json().get("items", [])
    if item.get("track")
    for artist in item["track"].get("artists", [])
    if artist.get("id")
}

if artist_ids:
    response = requests.put(
        f"{BASE_URL}/me/following",
        headers=headers,
        params={"type": "artist"},
        json={"ids": list(artist_ids)},
    )
    response.raise_for_status()

import os
import requests

BASE_URL = "https://api.spotify.com/v1"
headers = {"Authorization": f"Bearer {os.environ['SPOTIFY_ACCESS_TOKEN']}"}

# Remove all saved tracks and albums, paging through the library.
for endpoint, item_key in (("/me/tracks", "track"), ("/me/albums", "album")):
    url = f"{BASE_URL}{endpoint}"
    params = {"limit": 50}
    while url:
        response = requests.get(url, headers=headers, params=params)
        response.raise_for_status()
        data = response.json()
        ids = [
            item[item_key]["id"]
            for item in data.get("items", [])
            if item.get(item_key) and item[item_key].get("id")
        ]
        if ids:
            delete_response = requests.delete(
                f"{BASE_URL}{endpoint}",
                headers=headers,
                params={"ids": ",".join(ids)},
            )
            delete_response.raise_for_status()
        url = data.get("next")
        params = None

# Unfollow all followed artists, paging through the results.
url = f"{BASE_URL}/me/following"
params = {"type": "artist", "limit": 50}
while url:
    response = requests.get(url, headers=headers, params=params)
    response.raise_for_status()
    data = response.json().get("artists", {})
    artist_ids = [artist["id"] for artist in data.get("items", []) if artist.get("id")]
    if artist_ids:
        delete_response = requests.delete(
            f"{BASE_URL}/me/following",
            headers=headers,
            params={"type": "artist", "ids": ",".join(artist_ids)},
        )
        delete_response.raise_for_status()
    url = data.get("next")
    params = None

import os
import requests

BASE_URL = "https://api.spotify.com/v1"
headers = {"Authorization": f"Bearer {os.environ['SPOTIFY_ACCESS_TOKEN']}"}

playlists_response = requests.get(
    f"{BASE_URL}/me/playlists",
    headers=headers,
    params={"limit": 1},
)
playlists_response.raise_for_status()
playlists = playlists_response.json().get("items", [])

if playlists:
    playlist_id = playlists[0]["id"]
    tracks_response = requests.get(
        f"{BASE_URL}/playlists/{playlist_id}/tracks",
        headers=headers,
        params={"limit": 100},
    )
    tracks_response.raise_for_status()

    tracks = tracks_response.json().get("items", [])
    while tracks:
        requests.delete(
            f"{BASE_URL}/playlists/{playlist_id}/tracks",
            headers=headers,
            json={
                "tracks": [
                    {"uri": item["track"]["uri"]}
                    for item in tracks
                    if item.get("track") and item["track"].get("uri")
                ]
            },
        ).raise_for_status()

        next_url = tracks_response.json().get("next")
        if not next_url:
            break
        tracks_response = requests.get(next_url, headers=headers)
        tracks_response.raise_for_status()
        tracks = tracks_response.json().get("items", [])
